-- Migration to move Supreme Founder AI static data to DB

CREATE TABLE IF NOT EXISTS founder_client_leads (
  id VARCHAR(64) PRIMARY KEY,
  business_name VARCHAR(255),
  category VARCHAR(64),
  location VARCHAR(255),
  monthly_revenue_est VARCHAR(128),
  pain_point TEXT,
  project_budget INT,
  status VARCHAR(64),
  suggested_solution TEXT,
  potential_gmv_growth VARCHAR(128)
);

CREATE TABLE IF NOT EXISTS founder_remote_gigs (
  id VARCHAR(64) PRIMARY KEY,
  title VARCHAR(255),
  client_location VARCHAR(255),
  hourly_rate_usd INT,
  fixed_budget_usd INT,
  duration VARCHAR(128),
  skills_required JSONB,
  description TEXT,
  match_score INT,
  platform VARCHAR(128),
  proposal_template TEXT
);

CREATE TABLE IF NOT EXISTS founder_platforms (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255),
  category VARCHAR(64),
  description TEXT,
  icon VARCHAR(64),
  status VARCHAR(64),
  api_latency_ms INT,
  last_sync_time VARCHAR(64),
  auth_method VARCHAR(128),
  guardrail_protection JSONB,
  supported_actions JSONB
);

CREATE TABLE IF NOT EXISTS founder_separable_modules (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255),
  tagline VARCHAR(255),
  description TEXT,
  category VARCHAR(64),
  standalone_route VARCHAR(128),
  subdomain_url VARCHAR(255),
  files_count INT,
  bundle_size_kb INT,
  tech_stack JSONB,
  standalone_package_json JSONB,
  sample_component_code TEXT
);

CREATE TABLE IF NOT EXISTS founder_enterprise_blueprints (
  id VARCHAR(64) PRIMARY KEY,
  key_name VARCHAR(128) UNIQUE,
  title VARCHAR(255),
  category VARCHAR(64),
  target_organization VARCHAR(255),
  tech_stack JSONB,
  database_schema JSONB,
  api_endpoints JSONB,
  frontend_routes JSONB,
  live_preview_url VARCHAR(255),
  estimated_build_time VARCHAR(128),
  commercial_value_inr INT,
  client_handoff_ready BOOLEAN,
  handoff_credentials JSONB,
  files JSONB
);

TRUNCATE TABLE founder_client_leads;
TRUNCATE TABLE founder_remote_gigs;
TRUNCATE TABLE founder_platforms;
TRUNCATE TABLE founder_separable_modules;
TRUNCATE TABLE founder_enterprise_blueprints;

