INSERT INTO founder_remote_gigs (id, title, client_location, hourly_rate_usd, fixed_budget_usd, duration, skills_required, description, match_score, platform, proposal_template) VALUES ('REMOTE-501', 'Lead Distributed Systems Architect (FinTech Core)', 'San Francisco, CA (Remote)', 145, 28000, '3-6 Months', '["TypeScript","PostgreSQL","Distributed State Machines","Double-Entry Ledger","TanStack"]', 'Enterprise FinTech building high-throughput payment rails. Needs hands-on architect to design idempotent ledgers, zero-markup payment pipelines, and real-time reconciliation.', 99, 'Upwork Enterprise', 'Hi Hiring Team,
I specialize in building sovereign FinTech ledgers and zero-markup payment engines handling high-concurrency transactions. In my current production architecture, I built a double-entry ledger with PGlite memory caching, instant UPI/escrow settlement, and automated Section 79 IT Act compliance.

I can immediately deliver:
1. Idempotent payment state machine with zero double-charge risk.
2. High-performance PostgreSQL ledger with sub-50ms audit sweeps.
3. Clean, modular TypeScript/TanStack integration.

Let''s hop on a 15-minute sync to review my live architecture demo.');
INSERT INTO founder_remote_gigs (id, title, client_location, hourly_rate_usd, fixed_budget_usd, duration, skills_required, description, match_score, platform, proposal_template) VALUES ('REMOTE-502', 'Principal Full-Stack React 19 / Node Engineer', 'London, UK (Remote)', 125, 18500, '2-4 Months', '["React 19","TanStack Router","Tailwind CSS","WebSockets","Autonomous AI Agents"]', 'Scale-up building high-performance marketplace apps. Needs an expert who writes pristine, minimal diff code with zero placeholders.', 97, 'Toptal', 'Hi there,
I design and ship complete, production-grade marketplaces with React 19, TanStack Router, and real-time WebSockets dispatch. My code adheres to strict zero-placeholder standards, full type safety, and responsive glassmorphism UI.

Ready to start immediately and push clean, verified PRs from Day 1.');
INSERT INTO founder_remote_gigs (id, title, client_location, hourly_rate_usd, fixed_budget_usd, duration, skills_required, description, match_score, platform, proposal_template) VALUES ('REMOTE-503', 'Autonomous AI Agents & Multi-Modal Voice Systems Lead', 'Austin, TX (Remote)', 155, 32000, 'Ongoing / Retainer', '["Web Speech API","Gemini 2.5/Flash","AudioContext","Full Duplex Voice","Autonomous Workflows"]', 'AI startup building real-time executive voice assistants. Needs an engineer who has implemented real-time duplex voice turn-taking and multi-lingual voice synthesis.', 100, 'Direct US Client', 'Hi,
I have directly engineered full-duplex voice call systems with real-time audio waveform visualizers, native language auto-detection, and natural young female acoustic tuning (Web Speech + AudioContext).

I can integrate and benchmark this within your app within 48 hours. Let''s schedule a live voice demo.');

INSERT INTO founder_platforms (id, name, category, description, icon, status, api_latency_ms, last_sync_time, auth_method, guardrail_protection, supported_actions) VALUES ('plat-github', 'GitHub & DevOps Cloud', 'developer', 'Autonomous code synchronization, PR generation, branch protection enforcement, and CI/CD pipelines.', 'github', 'CONNECTED', 24, 'Just now', 'OAuth2 / HMAC-SHA256', '{"sandboxVerified":true,"zeroDataLeak":true,"rollbackSnapshotReady":true,"rateLimitSafe":true}', '[{"id":"act-gh-commit","label":"Force Autonomous Commit & Push","description":"Commits production bugfixes and features with zero merge conflicts.","safetyLevel":"STRICT_SAFE","defaultPayload":"git commit -m ''feat: sovereign core update'' && git push origin main"},{"id":"act-gh-ci","label":"Trigger 160-Suite Zero-Failure CI/CD","description":"Runs end-to-end automated test suites with deterministic assertion sweeps.","safetyLevel":"STRICT_SAFE","defaultPayload":"npm test && npm run typecheck && npm run build:dev"}]');
